import csv
from typing import Dict

def column_means(csv_text: str) -> Dict[str, float]:
    reader = csv.reader(csv_text.splitlines())
    headers = next(reader)
    column_means = {}

    for header in headers:
        values = [float(row) for row in reader if row and row[headers.index(header)]]
        if len(values) > 1:
            column_means[header] = sum(values) / len(values)

    return column_means
